def extostr(e: Exception, max_level: int = 30, max_path_level: int = 5) -> str:
    """Format an exception."""
    s = [str(e)]
    exc_type, exc_value, exc_tb = sys.exc_info()
    while exc_tb and max_level:
        s.append(f"{exc_tb.tb_frame.f_code.co_filename}:{exc_tb.tb_frame.f_code.co_firstlineno}:{exc_tb.tb_frame.f_code.co_name}")
        exc_type, exc_value, exc_tb = exc_tb.tb_next.exc_info()
        max_level -= 1
    return "\n".join(s)

