def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if isinstance(coord, tuple) and len(coord) == 2 and isinstance(coord[0], int) and isinstance(coord[1], int):
        x, y = coord
        width, height = self.bins
        if x >= 0 and x < width and y >= 0 and y < height:
            self.histogram[y][x] += weight
        else:
            pass
    else:
        raise ValueError("Invalid coordinate passed to fill() method. A tuple of two integers (x, y) is expected.")

def fill(self, coord, weight=1):
    coord_x, coord_y = coord
    if 0 <= coord_x < self.width and 0 <= coord_y < self.height:
        self.array[coord_y][coord_x] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if len(coord) != self.ndim:
        raise ValueError("Coordinate must have same number of dimensions as histogram")

    if (min(coord) < 0 or max(coord) >= self.shape[i] for i in range(self.ndim)):
        return

    for i in range(self.ndim):
        for j in range(self.shape[i]):
            if j < coord[i]:
                self[i, j] += weight
