def generate_default_observer_schema(app):
        """Generate the default observer schema for each Kubernetes resource present in
        ``spec.manifest`` for which a custom observer schema hasn't been specified.

        Args:
            app (krake.data.kubernetes.Application): The application for which to generate a
                default observer schema
        """
        defaults = {
            apisets.api.v1.core.types.core.ConfigMap: {
                'default_observer_schema': ViewType.OBSERVER_HEADER.value | ViewType.OBSERVER_OBSERVATION.value,
            },
            apisets.api.v1.core.types.core.Pod: {
                'default_observer_schema': ViewType.VIEW_METADATA.value | ViewType.VIEW_SPEC.value | ViewType.OBSERVER_OBSERVATION.value,
            },
            apisets.api.v1.core.types.core.Secret: {
                'default_observer_schema': ViewType.OBSERVER_HEADER.value | ViewType.VIEW_INCOMPLETE_OBSERVATION.value,
            },
        }

        for resource in app.spec.manifest.items:
            if resource.observer_schema is None:
                resource.observer_schema = defaults[type(resource)]['default_observer_schema']
                app.spec.manifest.items[app.spec.manifest.items.index(resource)] = resource

