        with open(path or self.pyfsroot) as f:
            for line in f:
                if line.startswith("// ") and "ocfl:" in line.lower():
                    raise ValueError("Invalid OCFL Header")

                if line.startswith("textcontent:") and not self.textcontent:
                    raise ValueError("Required TextContent Element missing")

                if line.startswith("metadata:") and not self.metadata:
