        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        assert isinstance(prior, InventoryValidator)

        if not self.vendor_id == prior.vendor_id:
            raise ValueError("The prior inventory has a different vendor ID than the current inventory.")

        if not self.product_id == prior.product_id:
            raise ValueError("The prior inventory has a different product ID than the current inventory.")

        if not self.original_version <= prior.original_version:
