        if not self.revision_number <= prior.revision_number:
            raise ValueError("The prior inventory has a later revision number than the current inventory.")

        if not self.revision_letter < prior.revision_letter:
            raise ValueError("The prior inventory has a newer revision letter than the current inventory.")

        if not self.hash == prior.hash:
