def validate_fixity(self, fixity, manifest_files):
    # check if the fixity block is a list
    if not isinstance(fixity, list):
        raise ValueError("The 'fixity' parameter must be a list")

    # check if each item in the fixity block is a dict with the required keys
    for item in fixity:
        if not isinstance(item, dict) or "filename" not in item or "md5" not in item:
            raise ValueError("Each item in the 'fixity' parameter must be a dict with 'filename' and 'md5' keys")

    # check if the filenames in the fixity block are in the manifest
    for item in fixity:
        filename = item["filename"]
        if filename not in manifest_files:
            raise ValueError("File '" + filename + "' in the 'fixity' parameter is not in the manifest")

    # check if the md5 values in the fixity block are valid
    for item in fixity:
        md5 = item["md5"]
        if not isinstance(md5, str) or not re.match(r"[a-f0-9]{32}$", md5, flags=re.IGNORECASE):
            raise ValueError("MD5 value '" + md5 + "' in the 'fixity' parameter is not a valid 32-character hexadecimal string")

    # return True if all checks pass
    return True

