        return self.pretty_standard(indent)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if indent == 0:
        result = ""
    else:
        result = " " * indent

    result += "<" + self.__class__.__name__ + ">"

    if indent > 0:
        result += "\n"

    for key, value in self.__dict__.items():
        new_indent = indent + 2
        if value is not None:
            if type(value) is list:
                result += pretty_list(value, new_indent, debug)
            else:
                result += pretty_item(key, value, new_indent, debug)
        elif debug:
