def size_to_bytes(size):
    # Replace the letter with a number (k/K = power of 10, m/M = power of 2, g/G = power of 3, etc.)
    size_suffix = {
        'k': 1000,
        'm': 1000000,
        'g': 1000000000,
        't': 1000000000000,
        'p': 1000000000000000,
        'e': 1000000000000000000
    }
    suffix = size_suffix.get(size[-1].lower(), 1)
    return int(float(size[:-1]) * suffix)

