def parse_frequency(frequency):
    if frequency is None or frequency == 'always':
        return None

    freq_parts = frequency.split(' ')
    if len(freq_parts) != 2:
        raise ValueError("Invalid frequency string: " + frequency)

    try:
        amount = int(freq_parts[0])
        unit = freq_parts[1]
    except:
        raise ValueError("Invalid frequency string: " + frequency)

    if unit == 'weeks':
        return datetime.timedelta(weeks=amount)
    elif unit == 'days':
