def _resolve_string(matcher):
    if not matcher.endswith('}'):
        raise ValueError("Invalid matcher {}. This is not a valid matcher.".format(matcher))
    name = matcher[1:-1]
    value = os.getenviron(name)
    default_value = matcher[-1] if matcher.endswith('|default') else None
    if not default_value:
        if not value:
            raise ValueError("Environment variable {} is not set".format(name))
        return value
    return default_value

