def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # load spec file content into a dict
    spec_dict = yaml.load(spec_content, Loader=yaml.SafeLoader)

    # check if the 'version' field is present
    if "version" not in spec_dict.keys():
        raise IRValidatorException("'version' field is missing in the spec file")

    # check if the 'metadata' field is present
    if "metadata" not in spec_dict.keys():
        raise IRValidatorException("'metadata' field is missing in the spec file")

    # check if the 'descriptors' field is present
    if "descriptors" not in spec_dict.keys():
        raise IRValidatorException("'descriptors' field is missing in the spec file")

    # check if the 'relations' field is present
    if "relations" not in spec_dict.keys():
        raise IRValidatorException("'relations' field is missing in the spec file")

    # check if the 'descriptors' field has all the required fields
    for descriptor in spec_dict["descriptors"]:
        if "class" not in descriptor.keys():
            raise IRValidatorException("'class' field is missing in the descriptor ")

        if "labels" not in descriptor.keys():
            raise IRValidatorException("'labels' field is missing in the descriptor ")

        if "description" not in descriptor.keys():
            raise IRValidatorException("'description' field is missing in the descriptor ")

    # check if the 'relations' field has all the required fields
    for relation in spec_dict["relations"]:
        if "relation" not in relation.keys():
            raise IRValidatorException("'relation' field is missing in the relation ")

        if "descriptor" not in relation.keys():
            raise IRValidatorException("'descriptor' field is missing in the relation ")

    # check if the 'metadata' field has all the required fields
    for meta in spec_dict["metadata"]:
        if "key" not in meta.keys():
            raise IRValidatorException("'key' field is missing in the metadata ")

        if "value" not in meta.keys():
            raise IRValidatorException("'value' field is missing in the metadata ")

    return spec_dict

def validate_from_content(spec_content=None):
    if spec_content is None:
        raise Exception("spec_content is required")

    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException("Error loading spec file: {0}".format(e))

    required_fields = ['ir_version', 'pipeline', 'svc_defs']

    for field in required_fields:
        if field not in spec:
            raise IRValidatorException("Missing required field {0} in spec file".format(field))

    return spec

