    ansible_args = ansible_args or {}
    extra_vars = extra_vars or {}
    # Get the playbook from the active workspace
    playbook = ir_workspace.get_object(playbook_path)
    if not playbook:
        raise Exception("Playbook not found in the workspace")

    # Build the argument list
    arglist = ["ansible-playbook", "-i", "localhost"]
    if verbose:
        arglist.extend(["-v", str(verbose)])
    if extra_vars:
        arglist.extend(["-e", extra_vars])
    for k, v in ansible_args.items():
        if isinstance(v, bool):
            if v is True:
                arglist.append(k)
            continue
        if isinstance(v, list):
            arglist.extend([k] + v)
            continue
        arglist.extend([k, str(v)])

    # Spawn a process to run the playbook
    process = Popen(arglist, shell=False, stdout=PIPE, stderr=PIPE)
    output, error = process.communicate()
    if process.returncode != 0:
        raise Exception("Failed to run ansible-playbook: {}".format(error.decode("utf-8")))
    return output.decode("utf-8")

